/**
 * Disposable S-3 evidence only.  This module intentionally models synthetic
 * documents, not an InteriorsEditor domain Project.  It exists solely to
 * observe browser durability boundaries under the narrow W-SPK-2026-08-04
 * waiver and must not be promoted into production.
 */

export class FaultInjectedError extends Error {
  constructor(boundary) {
    super(`Synthetic fault injected at ${boundary}`);
    this.name = 'FaultInjectedError';
    this.code = 'S3_FAULT_INJECTED';
    this.boundary = boundary;
  }
}

export class WriterFencedError extends Error {
  constructor() {
    super('The supplied writer lease is no longer current.');
    this.name = 'WriterFencedError';
    this.code = 'WRITER_FENCED';
  }
}

export class DurableStateConflictError extends Error {
  constructor() {
    super('Synthetic durable state changed before this command could publish.');
    this.name = 'DurableStateConflictError';
    this.code = 'DURABLE_STATE_CONFLICT';
  }
}

export class PendingDurabilityError extends Error {
  constructor() {
    super('A local durable publication is still pending; wait for it before recovery.');
    this.name = 'PendingDurabilityError';
    this.code = 'PENDING_DURABILITY_BUSY';
  }
}

export class RetentionRejectedError extends Error {
  constructor(rootCount, limit) {
    super(`Synthetic history would retain ${rootCount} roots, exceeding ${limit}.`);
    this.name = 'RetentionRejectedError';
    this.code = 'PROJECT_HISTORY_RESOURCE_LIMIT';
    this.rootCount = rootCount;
    this.limit = limit;
  }
}

export class RecoveryRequiredError extends Error {
  constructor(message, code = 'RESOURCE_RECOVERY_REQUIRED') {
    super(message);
    this.name = 'RecoveryRequiredError';
    this.code = code;
  }
}

function clone(value) {
  return structuredClone(value);
}

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) {
      deepFreeze(child);
    }
    Object.freeze(value);
  }
  return value;
}

function assertImmutableCandidate(revision) {
  if (!Object.isFrozen(revision) || !Object.isFrozen(revision.document) || !Object.isFrozen(revision.document.resources)) {
    throw new Error('Synthetic candidate must remain immutable before staging.');
  }
}

function canonicalize(value) {
  if (Array.isArray(value)) {
    return `[${value.map(canonicalize).join(',')}]`;
  }
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalize(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

async function checksumOf(value) {
  const bytes = new TextEncoder().encode(canonicalize(value));
  const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

function requestValue(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB request failed'));
  });
}

function transactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error('IndexedDB transaction failed'));
    transaction.onabort = () => reject(transaction.error ?? new Error('IndexedDB transaction aborted'));
  });
}

function openDatabase(indexedDBFactory, databaseName) {
  return new Promise((resolve, reject) => {
    const request = indexedDBFactory.open(databaseName, 1);
    request.onupgradeneeded = () => {
      const database = request.result;
      const staging = database.createObjectStore('staging', { keyPath: 'id' });
      staging.createIndex('projectId', 'projectId', { unique: false });
      const revisions = database.createObjectStore('revisions', { keyPath: 'id' });
      revisions.createIndex('projectId', 'projectId', { unique: false });
      database.createObjectStore('pointers', { keyPath: 'projectId' });
      database.createObjectStore('leases', { keyPath: 'projectId' });
      database.createObjectStore('histories', { keyPath: 'projectId' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB open failed'));
  });
}

function emptyHistory(projectId) {
  return {
    projectId,
    undoRevisionIds: [],
    redoRevisionIds: [],
    historyOnlyCorrupt: false,
    boundaryCount: 1
  };
}

function id(prefix) {
  return `${prefix}-${globalThis.crypto.randomUUID()}`;
}

function candidateDocument({ title, syntheticValue }) {
  return {
    schemaVersion: 1,
    kind: 'synthetic-s3-document',
    title,
    syntheticValue,
    resources: ['synthetic-resource-v1']
  };
}

const SYNTHETIC_FAULT_BOUNDARIES = new Set([
  null,
  'before-staging',
  'after-staging',
  'after-checksum',
  'before-pointer-swap',
  'after-pointer-swap'
]);

function assertNonEmptyString(value, label) {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new TypeError(`${label} must be a non-empty string.`);
  }
  return value;
}

function assertString(value, label) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string.`);
  }
  return value;
}

function assertPositiveSafeInteger(value, label) {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new RangeError(`${label} must be a positive safe integer.`);
  }
  return value;
}

function assertSafeInteger(value, label) {
  if (!Number.isSafeInteger(value)) {
    throw new TypeError(`${label} must be a safe integer.`);
  }
  return value;
}

function assertBoolean(value, label) {
  if (typeof value !== 'boolean') {
    throw new TypeError(`${label} must be a boolean.`);
  }
  return value;
}

function historyHasExpectedShape(history, projectId) {
  if (!history || typeof history !== 'object' || Array.isArray(history) || history.projectId !== projectId) {
    return false;
  }
  if (!Array.isArray(history.undoRevisionIds) || !Array.isArray(history.redoRevisionIds)) {
    return false;
  }
  const revisionIds = [...history.undoRevisionIds, ...history.redoRevisionIds];
  return revisionIds.every((revisionId) => typeof revisionId === 'string' && revisionId.trim().length > 0)
    && new Set(revisionIds).size === revisionIds.length
    && typeof history.historyOnlyCorrupt === 'boolean'
    && Number.isSafeInteger(history.boundaryCount)
    && history.boundaryCount > 0;
}

function pointerHasExpectedShape(pointer, projectId) {
  return Boolean(
    pointer
    && typeof pointer === 'object'
    && !Array.isArray(pointer)
    && pointer.projectId === projectId
    && typeof pointer.revisionId === 'string'
    && pointer.revisionId.trim().length > 0
    && typeof pointer.checksum === 'string'
    && pointer.checksum.trim().length > 0
  );
}

function assertKnownFaultBoundary(boundary) {
  if (!SYNTHETIC_FAULT_BOUNDARIES.has(boundary)) {
    throw new RangeError(`Unknown synthetic fault boundary: ${String(boundary)}.`);
  }
  return boundary;
}

export function createDurabilityCoordinator({
  indexedDBFactory = globalThis.indexedDB,
  databaseName = 's3-durability-spike',
  retentionMaxRoots = 3,
  faultAt = null,
  // Experimental test hook only; it is deliberately not a product interface.
  testOnlyBeforeCommit = undefined
} = {}) {
  if (!indexedDBFactory) {
    throw new Error('An IndexedDB factory is required for the S-3 experiment.');
  }
  assertPositiveSafeInteger(retentionMaxRoots, 'retentionMaxRoots');
  assertKnownFaultBoundary(faultAt);
  if (testOnlyBeforeCommit !== undefined && typeof testOnlyBeforeCommit !== 'function') {
    throw new TypeError('testOnlyBeforeCommit must be a function when provided.');
  }

  let databasePromise;
  let currentFault = faultAt;
  let currentRetentionMaxRoots = retentionMaxRoots;
  // This only tracks work executing in this coordinator; it is not a
  // cross-context fence. Persisted stages outside this Map remain recoverable.
  const activeStaging = new Map();

  async function database() {
    databasePromise ??= openDatabase(indexedDBFactory, databaseName);
    return databasePromise;
  }

  async function read(storeName, key) {
    const db = await database();
    const transaction = db.transaction(storeName, 'readonly');
    const result = await requestValue(transaction.objectStore(storeName).get(key));
    await transactionDone(transaction);
    return result === undefined ? undefined : clone(result);
  }

  async function readAll(storeName) {
    const db = await database();
    const transaction = db.transaction(storeName, 'readonly');
    const values = await requestValue(transaction.objectStore(storeName).getAll());
    await transactionDone(transaction);
    return clone(values);
  }

  async function readPointerAndHistory(projectId) {
    const db = await database();
    const transaction = db.transaction(['pointers', 'histories'], 'readonly');
    const [pointer, history] = await Promise.all([
      requestValue(transaction.objectStore('pointers').get(projectId)),
      requestValue(transaction.objectStore('histories').get(projectId))
    ]);
    await transactionDone(transaction);
    return {
      pointer: pointer === undefined ? undefined : clone(pointer),
      history: history === undefined ? undefined : clone(history)
    };
  }

  async function readProjectEvidence(projectId, history) {
    const [revisions, staging] = await Promise.all([
      readAll('revisions'),
      readAll('staging')
    ]);
    const projectStaging = staging.filter((record) => record.projectId === projectId);
    return {
      hasHistory: history !== undefined,
      hasRevision: revisions.some((revision) => revision.projectId === projectId),
      hasStaging: projectStaging.length > 0,
      hasStaleStaging: projectStaging.some((record) => !activeStaging.has(record.id))
    };
  }

  async function maybeFault(boundary, ignoreFaults) {
    if (!ignoreFaults && currentFault === boundary) {
      throw new FaultInjectedError(boundary);
    }
  }

  async function pauseBeforeCommit(operation, projectId) {
    await testOnlyBeforeCommit?.(Object.freeze({ operation, projectId }));
  }

  function leaseMatches(actual, lease) {
    return Boolean(
      lease
      && actual
      && actual.ownerId === lease.ownerId
      && actual.fence === lease.fence
    );
  }

  async function assertCurrentLease(projectId, lease) {
    assertNonEmptyString(projectId, 'projectId');
    const actual = await read('leases', projectId);
    if (!leaseMatches(actual, lease)) {
      throw new WriterFencedError();
    }
  }

  function pointerRecoveryRequired() {
    return new RecoveryRequiredError(
      'Synthetic durable pointer is missing or malformed.',
      'POINTER_MISSING_OR_MALFORMED'
    );
  }

  function stagingRecoveryRequired() {
    return new RecoveryRequiredError(
      'Synthetic staging requires explicit recovery before creating a project.',
      'STAGING_RECOVERY_REQUIRED'
    );
  }

  function markStagingActive(stagingRecord, lease) {
    activeStaging.set(stagingRecord.id, {
      projectId: stagingRecord.projectId,
      ownerId: lease.ownerId,
      fence: lease.fence
    });
  }

  function clearActiveStaging(stagingRecord) {
    if (stagingRecord) activeStaging.delete(stagingRecord.id);
  }

  function hasActiveStagingForLease(projectId, lease) {
    return [...activeStaging.values()].some((stage) => (
      stage.projectId === projectId
      && stage.ownerId === lease.ownerId
      && stage.fence === lease.fence
    ));
  }

  function requireUsableHistory(projectId, history) {
    if (!historyHasExpectedShape(history, projectId)) {
      throw new RecoveryRequiredError(
        'Synthetic session history is missing or malformed.',
        'HISTORY_MISSING_OR_MALFORMED'
      );
    }
    return history;
  }

  async function getUsableHistoryRoot(projectId, revisionId) {
    const revision = await read('revisions', revisionId);
    if (
      !revision
      || revision.id !== revisionId
      || revision.projectId !== projectId
      || !Number.isSafeInteger(revision.sequence)
      || revision.sequence <= 0
    ) {
      return undefined;
    }
    try {
      const actual = await checksumOf({
        id: revision.id,
        projectId: revision.projectId,
        sequence: revision.sequence,
        document: revision.document
      });
      return actual === revision.checksum ? deepFreeze(revision) : undefined;
    } catch {
      return undefined;
    }
  }

  async function findInvalidHistoryRoot(projectId, history, currentRevisionId = undefined) {
    for (const revisionId of [...history.undoRevisionIds, ...history.redoRevisionIds]) {
      if (revisionId === currentRevisionId || !await getUsableHistoryRoot(projectId, revisionId)) return revisionId;
    }
    return undefined;
  }

  async function classifyHistoryCorruption(projectId, history, currentRevisionId = undefined) {
    if (!historyHasExpectedShape(history, projectId)) return 'HISTORY_MISSING_OR_MALFORMED';
    if (history.historyOnlyCorrupt) return 'HISTORY_ALREADY_MARKED_CORRUPT';
    return (await findInvalidHistoryRoot(projectId, history, currentRevisionId)) ? 'HISTORY_TARGET_CORRUPT' : undefined;
  }

  function snapshotsMatch(actual, expected) {
    return canonicalize(actual) === canonicalize(expected);
  }

  async function commitPreconditionError(transaction, {
    projectId,
    lease,
    expectedPointer,
    expectedHistory
  }) {
    const [actualLease, actualPointer, actualHistory] = await Promise.all([
      requestValue(transaction.objectStore('leases').get(projectId)),
      requestValue(transaction.objectStore('pointers').get(projectId)),
      requestValue(transaction.objectStore('histories').get(projectId))
    ]);
    if (!leaseMatches(actualLease, lease)) return new WriterFencedError();
    if (!snapshotsMatch(actualPointer, expectedPointer) || !snapshotsMatch(actualHistory, expectedHistory)) {
      return new DurableStateConflictError();
    }
    return undefined;
  }

  async function abortCommit(transaction, completion, error) {
    transaction.abort();
    await completion.catch(() => undefined);
    throw error;
  }

  async function nextSequence(projectId) {
    const revisions = (await readAll('revisions')).filter((revision) => revision.projectId === projectId);
    return revisions.reduce((highest, revision) => Math.max(highest, revision.sequence), 0) + 1;
  }

  async function immutableCandidate({ projectId, document }) {
    const sequence = await nextSequence(projectId);
    const revision = {
      id: id('synthetic-revision'),
      projectId,
      sequence,
      document: clone(document)
    };
    const checksum = await checksumOf(revision);
    return deepFreeze({ ...revision, checksum });
  }

  async function stageCandidate(revision, { ignoreFaults }) {
    assertImmutableCandidate(revision);
    await maybeFault('before-staging', ignoreFaults);
    const db = await database();
    const stagingRecord = {
      id: id('synthetic-stage'),
      projectId: revision.projectId,
      revision: clone(revision),
      checksum: revision.checksum
    };
    const transaction = db.transaction('staging', 'readwrite');
    transaction.objectStore('staging').put(stagingRecord);
    await transactionDone(transaction);
    await maybeFault('after-staging', ignoreFaults);
    return stagingRecord;
  }

  async function verifyStage(stagingRecord, { ignoreFaults }) {
    const actual = await checksumOf({
      id: stagingRecord.revision.id,
      projectId: stagingRecord.revision.projectId,
      sequence: stagingRecord.revision.sequence,
      document: stagingRecord.revision.document
    });
    if (actual !== stagingRecord.checksum || actual !== stagingRecord.revision.checksum) {
      throw new RecoveryRequiredError('Synthetic staging checksum mismatch.', 'STAGING_CHECKSUM_MISMATCH');
    }
    await maybeFault('after-checksum', ignoreFaults);
  }

  async function publishStage(stagingRecord, nextHistory, {
    ignoreFaults,
    lease,
    expectedPointer,
    expectedHistory
  }) {
    await maybeFault('before-pointer-swap', ignoreFaults);
    await pauseBeforeCommit('publish-stage', stagingRecord.revision.projectId);
    const db = await database();
    const transaction = db.transaction(['revisions', 'pointers', 'histories', 'staging', 'leases'], 'readwrite');
    const completion = transactionDone(transaction);
    const revision = clone(stagingRecord.revision);
    const pointer = {
      projectId: revision.projectId,
      revisionId: revision.id,
      checksum: revision.checksum
    };
    const [stageInTransaction, preconditionError] = await Promise.all([
      requestValue(transaction.objectStore('staging').get(stagingRecord.id)),
      commitPreconditionError(transaction, {
        projectId: revision.projectId,
        lease,
        expectedPointer,
        expectedHistory
      })
    ]);
    if (preconditionError instanceof WriterFencedError) {
      await abortCommit(transaction, completion, preconditionError);
    }
    if (preconditionError || !snapshotsMatch(stageInTransaction, stagingRecord)) {
      if (snapshotsMatch(stageInTransaction, stagingRecord)) {
        transaction.objectStore('staging').delete(stagingRecord.id);
      }
      await completion;
      throw new DurableStateConflictError();
    }
    transaction.objectStore('revisions').put(revision);
    transaction.objectStore('pointers').put(pointer);
    transaction.objectStore('histories').put(clone(nextHistory));
    transaction.objectStore('staging').delete(stagingRecord.id);
    await completion;
    await maybeFault('after-pointer-swap', ignoreFaults);
    return { revision: deepFreeze(revision), pointer: deepFreeze(pointer) };
  }

  async function clearStaging({ projectId, lease, expectedPointer, expectedHistory }) {
    const records = (await readAll('staging')).filter((record) => record.projectId === projectId);
    if (records.length === 0) return false;
    await pauseBeforeCommit('recovery-staging-delete', projectId);
    const db = await database();
    const transaction = db.transaction(['staging', 'pointers', 'histories', 'leases'], 'readwrite');
    const completion = transactionDone(transaction);
    const store = transaction.objectStore('staging');
    const [preconditionError, currentRecords] = await Promise.all([
      commitPreconditionError(transaction, { projectId, lease, expectedPointer, expectedHistory }),
      Promise.all(records.map((record) => requestValue(store.get(record.id))))
    ]);
    if (preconditionError) {
      await abortCommit(transaction, completion, preconditionError);
    }
    if (currentRecords.some((record, index) => !snapshotsMatch(record, records[index]))) {
      await abortCommit(transaction, completion, new DurableStateConflictError());
    }
    for (const record of records) store.delete(record.id);
    await completion;
    return true;
  }

  async function preflightRetention({ pointer, history, candidateId }) {
    const roots = new Set([
      ...(pointer ? [pointer.revisionId] : []),
      ...(history?.undoRevisionIds ?? []),
      ...(history?.redoRevisionIds ?? []),
      candidateId
    ]);
    if (roots.size > currentRetentionMaxRoots) {
      throw new RetentionRejectedError(roots.size, currentRetentionMaxRoots);
    }
  }

  async function getRevisionForPointer(projectId, pointer) {
    if (!pointer) return undefined;
    const revision = await read('revisions', pointer.revisionId);
    if (!revision) {
      throw new RecoveryRequiredError('Pointer references a missing synthetic revision.', 'POINTER_TARGET_MISSING');
    }
    if (pointer.projectId !== projectId || revision.projectId !== projectId) {
      throw new RecoveryRequiredError('Pointer references a revision from another synthetic project.', 'POINTER_PROJECT_MISMATCH');
    }
    const actual = await checksumOf({
      id: revision.id,
      projectId: revision.projectId,
      sequence: revision.sequence,
      document: revision.document
    });
    if (actual !== pointer.checksum || actual !== revision.checksum) {
      throw new RecoveryRequiredError('Synthetic durable revision checksum mismatch.', 'DURABLE_CHECKSUM_MISMATCH');
    }
    return deepFreeze(revision);
  }

  async function requireCurrentDurableRevision(projectId, pointer, history) {
    if (!pointer) {
      const evidence = await readProjectEvidence(projectId, history);
      if (evidence.hasHistory || evidence.hasRevision) {
        throw pointerRecoveryRequired();
      }
      throw new RecoveryRequiredError(
        'A current durable revision is required for this command.',
        'NO_DURABLE_REVISION'
      );
    }
    if (!pointerHasExpectedShape(pointer, projectId)) {
      throw pointerRecoveryRequired();
    }
    try {
      return await getRevisionForPointer(projectId, pointer);
    } catch (error) {
      if (error instanceof RecoveryRequiredError) throw pointerRecoveryRequired();
      throw error;
    }
  }

  async function assertProjectCanCreate(projectId, pointer, history) {
    if (!pointer) {
      const evidence = await readProjectEvidence(projectId, history);
      if (evidence.hasHistory || evidence.hasRevision) {
        throw pointerRecoveryRequired();
      }
      if (evidence.hasStaleStaging) {
        throw stagingRecoveryRequired();
      }
      return;
    }
    if (!pointerHasExpectedShape(pointer, projectId)) {
      throw pointerRecoveryRequired();
    }
    try {
      await getRevisionForPointer(projectId, pointer);
    } catch (error) {
      if (error instanceof RecoveryRequiredError) throw pointerRecoveryRequired();
      throw error;
    }
    throw new Error('Synthetic project already exists.');
  }

  async function writeHistoryWithLease({
    projectId,
    history,
    lease,
    operation,
    expectedPointer,
    expectedHistory
  }) {
    await pauseBeforeCommit(operation, projectId);
    const db = await database();
    const transaction = db.transaction(['pointers', 'histories', 'leases'], 'readwrite');
    const completion = transactionDone(transaction);
    const preconditionError = await commitPreconditionError(transaction, {
      projectId,
      lease,
      expectedPointer,
      expectedHistory
    });
    if (preconditionError) {
      await abortCommit(transaction, completion, preconditionError);
    }
    transaction.objectStore('histories').put(clone(history));
    await completion;
  }

  async function markHistoryCorrupt({ projectId, history, lease, expectedPointer, expectedHistory }) {
    await writeHistoryWithLease({
      projectId,
      history: { ...history, projectId, historyOnlyCorrupt: true },
      lease,
      operation: 'mark-history-corrupt',
      expectedPointer,
      expectedHistory
    });
  }

  async function requireHealthyHistoryForCommand({
    projectId,
    history,
    lease,
    expectedPointer,
    expectedHistory,
    currentRevisionId
  }) {
    const usableHistory = requireUsableHistory(projectId, history);
    if (usableHistory.historyOnlyCorrupt) {
      throw new RecoveryRequiredError('Session history is corrupt and requires explicit resolution.');
    }
    if (await findInvalidHistoryRoot(projectId, usableHistory, currentRevisionId)) {
      await markHistoryCorrupt({
        projectId,
        history: usableHistory,
        lease,
        expectedPointer,
        expectedHistory
      });
      throw new RecoveryRequiredError(
        'Synthetic history target is corrupt and requires explicit history resolution.',
        'HISTORY_TARGET_CORRUPT'
      );
    }
    return usableHistory;
  }

  async function requireUsableHistoryTarget({
    projectId,
    revisionId,
    history,
    lease,
    expectedPointer,
    expectedHistory
  }) {
    const revision = await getUsableHistoryRoot(projectId, revisionId);
    if (!revision) {
      await markHistoryCorrupt({ projectId, history, lease, expectedPointer, expectedHistory });
      throw new RecoveryRequiredError(
        'Synthetic history target is corrupt and requires explicit history resolution.',
        'HISTORY_TARGET_CORRUPT'
      );
    }
    return deepFreeze(revision);
  }

  async function writeExistingPointerAndHistory({
    projectId,
    revision,
    history,
    lease,
    expectedPointer,
    expectedHistory
  }) {
    await pauseBeforeCommit('existing-pointer-and-history', projectId);
    const db = await database();
    const transaction = db.transaction(['pointers', 'histories', 'leases'], 'readwrite');
    const completion = transactionDone(transaction);
    const preconditionError = await commitPreconditionError(transaction, {
      projectId,
      lease,
      expectedPointer,
      expectedHistory
    });
    if (preconditionError) {
      await abortCommit(transaction, completion, preconditionError);
    }
    transaction.objectStore('pointers').put({
      projectId,
      revisionId: revision.id,
      checksum: revision.checksum
    });
    transaction.objectStore('histories').put(clone(history));
    await completion;
  }

  return {
    async acquireWriter(projectId, ownerId, { takeover = false } = {}) {
      assertNonEmptyString(projectId, 'projectId');
      assertNonEmptyString(ownerId, 'ownerId');
      assertBoolean(takeover, 'takeover');
      const db = await database();
      const transaction = db.transaction('leases', 'readwrite');
      const store = transaction.objectStore('leases');
      const existing = await requestValue(store.get(projectId));
      if (existing && existing.ownerId !== ownerId && !takeover) {
        transaction.abort();
        throw new WriterFencedError();
      }
      const lease = {
        projectId,
        ownerId,
        fence: (existing?.fence ?? 0) + (existing?.ownerId === ownerId ? 0 : 1)
      };
      store.put(lease);
      await transactionDone(transaction);
      return deepFreeze(lease);
    },

    setFaultAt(boundary) {
      currentFault = assertKnownFaultBoundary(boundary);
    },

    setRetentionMaxRoots(limit) {
      currentRetentionMaxRoots = assertPositiveSafeInteger(limit, 'retentionMaxRoots');
    },

    async createSyntheticProject({ projectId, title = 'Synthetic project', lease, ignoreFaults = false }) {
      assertNonEmptyString(projectId, 'projectId');
      assertString(title, 'title');
      assertBoolean(ignoreFaults, 'ignoreFaults');
      await assertCurrentLease(projectId, lease);
      const { pointer: expectedPointer, history: expectedHistory } = await readPointerAndHistory(projectId);
      await assertProjectCanCreate(projectId, expectedPointer, expectedHistory);
      const revision = await immutableCandidate({
        projectId,
        document: candidateDocument({ title, syntheticValue: 0 })
      });
      await preflightRetention({ pointer: expectedPointer, history: expectedHistory, candidateId: revision.id });
      let stagingRecord;
      try {
        stagingRecord = await stageCandidate(revision, { ignoreFaults });
        markStagingActive(stagingRecord, lease);
        await verifyStage(stagingRecord, { ignoreFaults });
        const result = await publishStage(stagingRecord, emptyHistory(projectId), {
          ignoreFaults,
          lease,
          expectedPointer,
          expectedHistory
        });
        return { status: 'durable', ...result };
      } finally {
        clearActiveStaging(stagingRecord);
      }
    },

    async mutateSyntheticValue({ projectId, lease, delta = 1, ignoreFaults = false }) {
      assertNonEmptyString(projectId, 'projectId');
      assertSafeInteger(delta, 'delta');
      assertBoolean(ignoreFaults, 'ignoreFaults');
      await assertCurrentLease(projectId, lease);
      const { pointer: expectedPointer, history: storedHistory } = await readPointerAndHistory(projectId);
      const shapedHistory = requireUsableHistory(projectId, storedHistory);
      if (shapedHistory.historyOnlyCorrupt) {
        throw new RecoveryRequiredError('Session history is corrupt and requires explicit resolution.');
      }
      const current = await requireCurrentDurableRevision(projectId, expectedPointer, storedHistory);
      const history = await requireHealthyHistoryForCommand({
        projectId,
        history: shapedHistory,
        lease,
        expectedPointer,
        expectedHistory: storedHistory,
        currentRevisionId: current.id
      });
      const syntheticValue = current.document.syntheticValue + delta;
      if (!Number.isSafeInteger(syntheticValue)) {
        throw new RangeError('syntheticValue must remain a safe integer.');
      }
      const revision = await immutableCandidate({
        projectId,
        document: candidateDocument({
          title: current.document.title,
          syntheticValue
        })
      });
      await preflightRetention({ pointer: expectedPointer, history, candidateId: revision.id });
      const nextHistory = {
        ...history,
        undoRevisionIds: [...history.undoRevisionIds, current.id],
        redoRevisionIds: []
      };
      let stagingRecord;
      try {
        stagingRecord = await stageCandidate(revision, { ignoreFaults });
        markStagingActive(stagingRecord, lease);
        await verifyStage(stagingRecord, { ignoreFaults });
        const result = await publishStage(stagingRecord, nextHistory, {
          ignoreFaults,
          lease,
          expectedPointer,
          expectedHistory: history
        });
        return { status: 'durable', ...result };
      } finally {
        clearActiveStaging(stagingRecord);
      }
    },

    async undo({ projectId, lease }) {
      assertNonEmptyString(projectId, 'projectId');
      await assertCurrentLease(projectId, lease);
      const { pointer: expectedPointer, history: storedHistory } = await readPointerAndHistory(projectId);
      const shapedHistory = requireUsableHistory(projectId, storedHistory);
      if (shapedHistory.historyOnlyCorrupt) {
        throw new RecoveryRequiredError('Session history is corrupt and requires explicit resolution.');
      }
      const current = await requireCurrentDurableRevision(projectId, expectedPointer, storedHistory);
      const history = await requireHealthyHistoryForCommand({
        projectId,
        history: shapedHistory,
        lease,
        expectedPointer,
        expectedHistory: storedHistory,
        currentRevisionId: current.id
      });
      const priorId = history.undoRevisionIds.at(-1);
      if (!priorId) return { status: 'no-undo', revision: current };
      const prior = await requireUsableHistoryTarget({
        projectId,
        revisionId: priorId,
        history,
        lease,
        expectedPointer,
        expectedHistory: history
      });
      const nextHistory = {
        ...history,
        undoRevisionIds: history.undoRevisionIds.slice(0, -1),
        redoRevisionIds: [current.id, ...history.redoRevisionIds]
      };
      await writeExistingPointerAndHistory({
        projectId,
        revision: prior,
        history: nextHistory,
        lease,
        expectedPointer,
        expectedHistory: history
      });
      return { status: 'durable', revision: deepFreeze(prior) };
    },

    async redo({ projectId, lease }) {
      assertNonEmptyString(projectId, 'projectId');
      await assertCurrentLease(projectId, lease);
      const { pointer: expectedPointer, history: storedHistory } = await readPointerAndHistory(projectId);
      const shapedHistory = requireUsableHistory(projectId, storedHistory);
      if (shapedHistory.historyOnlyCorrupt) {
        throw new RecoveryRequiredError('Session history is corrupt and requires explicit resolution.');
      }
      const current = await requireCurrentDurableRevision(projectId, expectedPointer, storedHistory);
      const history = await requireHealthyHistoryForCommand({
        projectId,
        history: shapedHistory,
        lease,
        expectedPointer,
        expectedHistory: storedHistory,
        currentRevisionId: current.id
      });
      const nextId = history.redoRevisionIds.at(0);
      if (!nextId) return { status: 'no-redo', revision: current };
      const next = await requireUsableHistoryTarget({
        projectId,
        revisionId: nextId,
        history,
        lease,
        expectedPointer,
        expectedHistory: history
      });
      const nextHistory = {
        ...history,
        undoRevisionIds: [...history.undoRevisionIds, current.id],
        redoRevisionIds: history.redoRevisionIds.slice(1)
      };
      await writeExistingPointerAndHistory({
        projectId,
        revision: next,
        history: nextHistory,
        lease,
        expectedPointer,
        expectedHistory: history
      });
      return { status: 'durable', revision: deepFreeze(next) };
    },

    async recoverProject(projectId, lease) {
      assertNonEmptyString(projectId, 'projectId');
      await assertCurrentLease(projectId, lease);
      if (hasActiveStagingForLease(projectId, lease)) {
        throw new PendingDurabilityError();
      }
      const { pointer: expectedPointer, history: expectedHistory } = await readPointerAndHistory(projectId);
      if (!expectedPointer) {
        const evidence = await readProjectEvidence(projectId, expectedHistory);
        if (evidence.hasHistory || evidence.hasRevision) {
          throw pointerRecoveryRequired();
        }
        if (evidence.hasStaging) {
          const stagingCleaned = await clearStaging({
            projectId,
            lease,
            expectedPointer,
            expectedHistory
          });
          return { status: 'no-durable-revision-recovered', revision: undefined, stagingCleaned };
        }
        return { status: 'no-durable-revision', revision: undefined };
      }
      if (!pointerHasExpectedShape(expectedPointer, projectId)) {
        throw pointerRecoveryRequired();
      }
      const revision = await getRevisionForPointer(projectId, expectedPointer);
      await clearStaging({ projectId, lease, expectedPointer, expectedHistory });
      return { status: 'recovered', revision };
    },

    async markHistoryOnlyCorrupt(projectId, lease) {
      assertNonEmptyString(projectId, 'projectId');
      await assertCurrentLease(projectId, lease);
      const { pointer: expectedPointer, history: storedHistory } = await readPointerAndHistory(projectId);
      const history = requireUsableHistory(projectId, storedHistory);
      await requireCurrentDurableRevision(projectId, expectedPointer, storedHistory);
      await markHistoryCorrupt({
        projectId,
        history,
        lease,
        expectedPointer,
        expectedHistory: history
      });
    },

    async discardSessionHistory({ projectId, confirmed, lease }) {
      assertNonEmptyString(projectId, 'projectId');
      assertBoolean(confirmed, 'confirmed');
      await assertCurrentLease(projectId, lease);
      const { pointer: expectedPointer, history: storedHistory } = await readPointerAndHistory(projectId);
      const historyCorruption = await classifyHistoryCorruption(
        projectId,
        storedHistory,
        expectedPointer?.revisionId
      );
      if (!historyCorruption) {
        throw new RecoveryRequiredError('There is no history-only corruption to discard.', 'HISTORY_NOT_CORRUPT');
      }
      if (!confirmed) {
        return { status: 'cancelled', createdProjectRevision: false };
      }
      const hasUsableBoundaryCount = historyHasExpectedShape(storedHistory, projectId);
      if (hasUsableBoundaryCount && storedHistory.boundaryCount === Number.MAX_SAFE_INTEGER) {
        throw new RecoveryRequiredError(
          'Synthetic session history cannot increment its boundary count safely.',
          'HISTORY_BOUNDARY_LIMIT'
        );
      }
      if (!expectedPointer || !pointerHasExpectedShape(expectedPointer, projectId)) {
        await requireCurrentDurableRevision(projectId, expectedPointer, storedHistory);
      }
      await getRevisionForPointer(projectId, expectedPointer);
      const nextHistory = {
        ...emptyHistory(projectId),
        boundaryCount: hasUsableBoundaryCount
          ? storedHistory.boundaryCount + 1
          : 1
      };
      await writeHistoryWithLease({
        projectId,
        history: nextHistory,
        lease,
        operation: 'discard-session-history',
        expectedPointer,
        expectedHistory: storedHistory
      });
      return { status: 'discarded', createdProjectRevision: false, boundaryCount: nextHistory.boundaryCount };
    },

    async readPointer(projectId) {
      assertNonEmptyString(projectId, 'projectId');
      return read('pointers', projectId);
    },

    async readStagingCount(projectId) {
      assertNonEmptyString(projectId, 'projectId');
      return (await readAll('staging')).filter((record) => record.projectId === projectId).length;
    },

    async inspectHistory(projectId) {
      assertNonEmptyString(projectId, 'projectId');
      const history = await read('histories', projectId);
      return history ?? emptyHistory(projectId);
    },

    async getDurableState(projectId) {
      assertNonEmptyString(projectId, 'projectId');
      const { pointer, history } = await readPointerAndHistory(projectId);
      if (!pointer) {
        const evidence = await readProjectEvidence(projectId, history);
        if (evidence.hasHistory || evidence.hasRevision) {
          throw pointerRecoveryRequired();
        }
        return { exists: false };
      }
      if (!pointerHasExpectedShape(pointer, projectId)) {
        throw pointerRecoveryRequired();
      }
      const revision = await getRevisionForPointer(projectId, pointer);
      return { exists: true, pointer, revision, history };
    }
  };
}

