import { expect, test } from 'vitest';
import { indexedDB as fakeIndexedDB } from 'fake-indexeddb';

import {
  FaultInjectedError,
  RecoveryRequiredError,
  RetentionRejectedError,
  WriterFencedError,
  createDurabilityCoordinator
} from '../../src/durability.mjs';

function makeCoordinator(options = {}) {
  return createDurabilityCoordinator({
    indexedDBFactory: fakeIndexedDB,
    databaseName: `s3-unit-${crypto.randomUUID()}`,
    ...options
  });
}

function openSyntheticDatabase(databaseName) {
  return new Promise((resolve, reject) => {
    const request = fakeIndexedDB.open(databaseName);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function requestResult(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function transactionComplete(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = resolve;
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error);
  });
}

async function replacePointer(databaseName, pointer) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('pointers', 'readwrite');
    const completed = transactionComplete(transaction);
    transaction.objectStore('pointers').put(pointer);
    await completed;
  } finally {
    database.close();
  }
}

async function deletePointer(databaseName, projectId) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('pointers', 'readwrite');
    const completed = transactionComplete(transaction);
    transaction.objectStore('pointers').delete(projectId);
    await completed;
  } finally {
    database.close();
  }
}

async function readStoredRevisions(databaseName, projectId) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('revisions', 'readonly');
    const revisions = await requestResult(transaction.objectStore('revisions').getAll());
    await transactionComplete(transaction);
    return revisions.filter((revision) => revision.projectId === projectId);
  } finally {
    database.close();
  }
}

async function deleteStoredRevisions(databaseName, projectId) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('revisions', 'readwrite');
    const store = transaction.objectStore('revisions');
    const revisions = await requestResult(store.getAll());
    const completed = transactionComplete(transaction);
    for (const revision of revisions) {
      if (revision.projectId === projectId) store.delete(revision.id);
    }
    await completed;
  } finally {
    database.close();
  }
}

async function replaceLease(databaseName, lease) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('leases', 'readwrite');
    const completed = transactionComplete(transaction);
    transaction.objectStore('leases').put(lease);
    await completed;
  } finally {
    database.close();
  }
}

async function replaceHistory(databaseName, history) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('histories', 'readwrite');
    const completed = transactionComplete(transaction);
    transaction.objectStore('histories').put(history);
    await completed;
  } finally {
    database.close();
  }
}

async function deleteHistory(databaseName, projectId) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('histories', 'readwrite');
    const completed = transactionComplete(transaction);
    transaction.objectStore('histories').delete(projectId);
    await completed;
  } finally {
    database.close();
  }
}

async function readStoredHistory(databaseName, projectId) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('histories', 'readonly');
    const history = await requestResult(transaction.objectStore('histories').get(projectId));
    await transactionComplete(transaction);
    return history;
  } finally {
    database.close();
  }
}

async function corruptRevisionDocument(databaseName, revisionId) {
  const database = await openSyntheticDatabase(databaseName);
  try {
    const transaction = database.transaction('revisions', 'readwrite');
    const store = transaction.objectStore('revisions');
    const revision = await requestResult(store.get(revisionId));
    const completed = transactionComplete(transaction);
    store.put({
      ...revision,
      document: { ...revision.document, title: `Corrupt ${revision.document.title}` }
    });
    await completed;
  } finally {
    database.close();
  }
}

function makeCommitGate() {
  let armed;

  return {
    async testOnlyBeforeCommit({ operation }) {
      if (!armed || armed.operation !== operation) return;
      const checkpoint = armed;
      armed = undefined;
      checkpoint.reached();
      await checkpoint.releasePromise;
    },

    arm(operation) {
      let reached;
      let release;
      const reachedPromise = new Promise((resolve) => {
        reached = resolve;
      });
      const releasePromise = new Promise((resolve) => {
        release = resolve;
      });
      armed = { operation, reached, releasePromise };
      return { wait: () => reachedPromise, release };
    }
  };
}

async function waitForCommit(checkpoint) {
  let timeout;
  try {
    await Promise.race([
      checkpoint.wait(),
      new Promise((_, reject) => {
        timeout = setTimeout(() => reject(new Error('The test-only commit checkpoint was not reached.')), 250);
      })
    ]);
  } finally {
    clearTimeout(timeout);
  }
}

test('rejects malformed public coordinator inputs before durable state changes', async () => {
  expect(() => makeCoordinator({ retentionMaxRoots: 0 })).toThrow(/positive safe integer/i);
  expect(() => makeCoordinator({ retentionMaxRoots: Number.MAX_SAFE_INTEGER + 1 })).toThrow(/positive safe integer/i);
  expect(() => makeCoordinator({ faultAt: 'outside-the-synthetic-boundaries' })).toThrow(/unknown synthetic fault boundary/i);

  const coordinator = makeCoordinator();
  await expect(coordinator.acquireWriter('', 'writer-a')).rejects.toThrow(/projectId must be a non-empty string/i);
  await expect(coordinator.acquireWriter('project-inputs', '   ')).rejects.toThrow(/ownerId must be a non-empty string/i);
  const lease = await coordinator.acquireWriter('project-inputs', 'writer-a');

  await expect(coordinator.createSyntheticProject({ projectId: 'project-inputs', title: 42, lease })).rejects.toThrow(/title must be a string/i);
  await coordinator.createSyntheticProject({ projectId: 'project-inputs', title: 'Valid title', lease });
  await expect(coordinator.mutateSyntheticValue({ projectId: 'project-inputs', lease, delta: 0.5 })).rejects.toThrow(/delta must be a safe integer/i);
  await expect(coordinator.mutateSyntheticValue({ projectId: 'project-inputs', lease, delta: Number.MAX_SAFE_INTEGER + 1 })).rejects.toThrow(/delta must be a safe integer/i);
  expect(() => coordinator.setRetentionMaxRoots(-1)).toThrow(/positive safe integer/i);
  expect(() => coordinator.setFaultAt('not-a-real-boundary')).toThrow(/unknown synthetic fault boundary/i);
  expect((await coordinator.getDurableState('project-inputs')).revision.document.syntheticValue).toBe(0);
});

test('a stale lease cannot mark a healthy history corrupt after takeover', async () => {
  const coordinator = makeCoordinator();
  const writerA = await coordinator.acquireWriter('project-stale-history-mark', 'writer-a');
  await coordinator.createSyntheticProject({ projectId: 'project-stale-history-mark', lease: writerA });
  const pointerBefore = await coordinator.readPointer('project-stale-history-mark');
  const historyBefore = await coordinator.inspectHistory('project-stale-history-mark');
  await coordinator.acquireWriter('project-stale-history-mark', 'writer-b', { takeover: true });

  await expect(coordinator.markHistoryOnlyCorrupt('project-stale-history-mark', writerA)).rejects.toMatchObject({
    code: 'WRITER_FENCED'
  });
  expect(await coordinator.readPointer('project-stale-history-mark')).toEqual(pointerBefore);
  expect(await coordinator.inspectHistory('project-stale-history-mark')).toEqual(historyBefore);
});

test('a stale lease cannot discard corrupt session history after takeover', async () => {
  const coordinator = makeCoordinator();
  const writerA = await coordinator.acquireWriter('project-stale-history-discard', 'writer-a');
  await coordinator.createSyntheticProject({ projectId: 'project-stale-history-discard', lease: writerA });
  await coordinator.markHistoryOnlyCorrupt('project-stale-history-discard', writerA);
  const pointerBefore = await coordinator.readPointer('project-stale-history-discard');
  const historyBefore = await coordinator.inspectHistory('project-stale-history-discard');
  await coordinator.acquireWriter('project-stale-history-discard', 'writer-b', { takeover: true });

  await expect(coordinator.discardSessionHistory({
    projectId: 'project-stale-history-discard',
    confirmed: true,
    lease: writerA
  })).rejects.toMatchObject({ code: 'WRITER_FENCED' });
  expect(await coordinator.readPointer('project-stale-history-discard')).toEqual(pointerBefore);
  expect(await coordinator.inspectHistory('project-stale-history-discard')).toEqual(historyBefore);
});

test('history cancellation requires a supplied current lease before returning its no-op result', async () => {
  const coordinator = makeCoordinator();
  const writerA = await coordinator.acquireWriter('project-history-cancel-lease', 'writer-a');
  await coordinator.createSyntheticProject({ projectId: 'project-history-cancel-lease', lease: writerA });
  await coordinator.markHistoryOnlyCorrupt('project-history-cancel-lease', writerA);

  await expect(coordinator.discardSessionHistory({
    projectId: 'project-history-cancel-lease',
    confirmed: false,
    lease: undefined
  })).rejects.toMatchObject({ code: 'WRITER_FENCED' });
  await coordinator.acquireWriter('project-history-cancel-lease', 'writer-b', { takeover: true });
  await expect(coordinator.discardSessionHistory({
    projectId: 'project-history-cancel-lease',
    confirmed: false,
    lease: writerA
  })).rejects.toMatchObject({ code: 'WRITER_FENCED' });
  expect((await coordinator.inspectHistory('project-history-cancel-lease')).historyOnlyCorrupt).toBe(true);
});

test('rejects non-boolean public controls before they can alter durable state', async () => {
  const takeoverCoordinator = makeCoordinator();
  await takeoverCoordinator.acquireWriter('project-boolean-takeover', 'writer-a');
  await expect(takeoverCoordinator.acquireWriter('project-boolean-takeover', 'writer-b', { takeover: 'true' })).rejects.toThrow(/takeover must be a boolean/i);

  const coordinator = makeCoordinator();
  const lease = await coordinator.acquireWriter('project-boolean-controls', 'writer-a');
  await expect(coordinator.createSyntheticProject({
    projectId: 'project-boolean-controls',
    lease,
    ignoreFaults: 'true'
  })).rejects.toThrow(/ignoreFaults must be a boolean/i);
  await coordinator.createSyntheticProject({ projectId: 'project-boolean-controls', lease });
  const pointerBefore = await coordinator.readPointer('project-boolean-controls');
  const historyBefore = await coordinator.inspectHistory('project-boolean-controls');
  await expect(coordinator.mutateSyntheticValue({
    projectId: 'project-boolean-controls',
    lease,
    delta: 5,
    ignoreFaults: 'false'
  })).rejects.toThrow(/ignoreFaults must be a boolean/i);
  await coordinator.markHistoryOnlyCorrupt('project-boolean-controls', lease);
  const corruptHistory = await coordinator.inspectHistory('project-boolean-controls');
  await expect(coordinator.discardSessionHistory({
    projectId: 'project-boolean-controls',
    lease,
    confirmed: 'false'
  })).rejects.toThrow(/confirmed must be a boolean/i);
  expect(await coordinator.readPointer('project-boolean-controls')).toEqual(pointerBefore);
  expect(historyBefore.historyOnlyCorrupt).toBe(false);
  expect(corruptHistory.historyOnlyCorrupt).toBe(true);
  expect(await coordinator.inspectHistory('project-boolean-controls')).toEqual(corruptHistory);
});

test('rejects a mutation whose resulting synthetic value is not a safe integer', async () => {
  const coordinator = makeCoordinator();
  const lease = await coordinator.acquireWriter('project-safe-result', 'writer-a');
  await coordinator.createSyntheticProject({ projectId: 'project-safe-result', lease });
  await coordinator.mutateSyntheticValue({
    projectId: 'project-safe-result',
    lease,
    delta: Number.MAX_SAFE_INTEGER
  });
  const pointerBefore = await coordinator.readPointer('project-safe-result');
  const historyBefore = await coordinator.inspectHistory('project-safe-result');

  await expect(coordinator.mutateSyntheticValue({
    projectId: 'project-safe-result',
    lease,
    delta: 1
  })).rejects.toThrow(/syntheticValue must remain a safe integer/i);
  expect((await coordinator.getDurableState('project-safe-result')).revision.document.syntheticValue).toBe(Number.MAX_SAFE_INTEGER);
  expect(await coordinator.readPointer('project-safe-result')).toEqual(pointerBefore);
  expect(await coordinator.inspectHistory('project-safe-result')).toEqual(historyBefore);
});

test('missing durable pointer with retained evidence enters controlled recovery instead of creating or mutating', async () => {
  const databaseName = `s3-pointer-missing-${crypto.randomUUID()}`;
  const coordinator = createDurabilityCoordinator({ indexedDBFactory: fakeIndexedDB, databaseName });
  const projectId = 'project-pointer-missing';
  const lease = await coordinator.acquireWriter(projectId, 'writer-a');
  await coordinator.createSyntheticProject({ projectId, title: 'Retained project', lease });
  await coordinator.mutateSyntheticValue({ projectId, lease, delta: 5 });
  const revisionsBefore = await readStoredRevisions(databaseName, projectId);
  const historyBefore = await readStoredHistory(databaseName, projectId);
  await deletePointer(databaseName, projectId);

  for (const command of [
    () => coordinator.createSyntheticProject({ projectId, title: 'Must not replace retained project', lease }),
    () => coordinator.mutateSyntheticValue({ projectId, lease, delta: 3 }),
    () => coordinator.undo({ projectId, lease }),
    () => coordinator.redo({ projectId, lease })
  ]) {
    await expect(command()).rejects.toMatchObject({
      name: 'RecoveryRequiredError',
      code: 'POINTER_MISSING_OR_MALFORMED'
    });
  }
  await expect(coordinator.recoverProject(projectId, lease)).rejects.toMatchObject({
    name: 'RecoveryRequiredError',
    code: 'POINTER_MISSING_OR_MALFORMED'
  });
  expect(await coordinator.readPointer(projectId)).toBeUndefined();
  expect(await readStoredRevisions(databaseName, projectId)).toEqual(revisionsBefore);
  expect(await readStoredHistory(databaseName, projectId)).toEqual(historyBefore);
  expect(await coordinator.readStagingCount(projectId)).toBe(0);

  const virginProjectId = 'project-pointer-virgin';
  const virginLease = await coordinator.acquireWriter(virginProjectId, 'writer-virgin');
  await expect(coordinator.createSyntheticProject({ projectId: virginProjectId, lease: virginLease })).resolves.toMatchObject({
    status: 'durable',
    revision: { sequence: 1 }
  });
});

test('durable-state query rejects a missing pointer when the project still retains durable evidence', async () => {
  const databaseName = `s3-query-pointer-missing-${crypto.randomUUID()}`;
  const coordinator = createDurabilityCoordinator({ indexedDBFactory: fakeIndexedDB, databaseName });
  const projectId = 'project-query-pointer-missing';
  const lease = await coordinator.acquireWriter(projectId, 'writer-a');
  await coordinator.createSyntheticProject({ projectId, lease });
  await coordinator.mutateSyntheticValue({ projectId, lease, delta: 2 });
  const revisionsBefore = await readStoredRevisions(databaseName, projectId);
  const historyBefore = await readStoredHistory(databaseName, projectId);
  await deletePointer(databaseName, projectId);

  await expect(coordinator.getDurableState(projectId)).rejects.toMatchObject({
    name: 'RecoveryRequiredError',
    code: 'POINTER_MISSING_OR_MALFORMED'
  });
  expect(await coordinator.readPointer(projectId)).toBeUndefined();
  expect(await readStoredRevisions(databaseName, projectId)).toEqual(revisionsBefore);
  expect(await readStoredHistory(databaseName, projectId)).toEqual(historyBefore);
  expect(await coordinator.readStagingCount(projectId)).toBe(0);

  const virginProjectId = 'project-query-virgin';
  await expect(coordinator.getDurableState(virginProjectId)).resolves.toEqual({ exists: false });
});

test('durable-state query treats either retained history or retained revisions as pointer-loss evidence', async () => {
  const databaseName = `s3-query-pointer-either-evidence-${crypto.randomUUID()}`;
  const coordinator = createDurabilityCoordinator({ indexedDBFactory: fakeIndexedDB, databaseName });
  const scenarios = [
    {
      projectId: 'project-query-history-only',
      remove: (projectId) => deleteStoredRevisions(databaseName, projectId)
    },
    {
