test('the local pending guard requires the exact project, owner and fence', async () => {
  const scenarios = [
    {
      name: 'project',
      recoveryProjectId: 'project-pending-guard-other',
      async recoveryLease({ coordinator }) {
        return coordinator.acquireWriter(this.recoveryProjectId, 'writer-shared');
      },
      recoveryResult: { status: 'no-durable-revision', revision: undefined },
      keepsLiveStage: true
    },
    {
      name: 'owner',
      recoveryProjectId: 'project-pending-guard-owner',
      async recoveryLease({ databaseName, liveLease }) {
        const lease = { ...liveLease, ownerId: 'writer-other' };
        await replaceLease(databaseName, lease);
        return lease;
      },
      recoveryResult: { status: 'no-durable-revision-recovered', revision: undefined, stagingCleaned: true },
      keepsLiveStage: false
    },
    {
      name: 'fence',
      recoveryProjectId: 'project-pending-guard-fence',
      async recoveryLease({ databaseName, liveLease }) {
        const lease = { ...liveLease, fence: liveLease.fence + 1 };
        await replaceLease(databaseName, lease);
        return lease;
      },
      recoveryResult: { status: 'no-durable-revision-recovered', revision: undefined, stagingCleaned: true },
      keepsLiveStage: false
    }
  ];

  for (const scenario of scenarios) {
    const databaseName = `s3-pending-guard-${scenario.name}-${crypto.randomUUID()}`;
    const gate = makeCommitGate();
    const coordinator = createDurabilityCoordinator({
      indexedDBFactory: fakeIndexedDB,
      databaseName,
      testOnlyBeforeCommit: gate.testOnlyBeforeCommit
    });
    const liveProjectId = scenario.name === 'project'
      ? 'project-pending-guard-live'
      : scenario.recoveryProjectId;
    const liveLease = await coordinator.acquireWriter(liveProjectId, 'writer-shared');
    const checkpoint = gate.arm('publish-stage');
    const pendingCreate = coordinator.createSyntheticProject({ projectId: liveProjectId, lease: liveLease });
    await waitForCommit(checkpoint);
    const recoveryLease = await scenario.recoveryLease({ coordinator, databaseName, liveLease });

    await expect(coordinator.recoverProject(scenario.recoveryProjectId, recoveryLease)).resolves.toEqual(scenario.recoveryResult);
    expect(await coordinator.readStagingCount(liveProjectId)).toBe(scenario.keepsLiveStage ? 1 : 0);

    checkpoint.release();
    if (scenario.keepsLiveStage) {
      await expect(pendingCreate).resolves.toMatchObject({ status: 'durable', revision: { sequence: 1 } });
    } else {
      await expect(pendingCreate).rejects.toMatchObject({ code: 'WRITER_FENCED' });
    }
  }
});

