test('retention rejection preserves current, undo and redo roots until a later successful publish replaces redo', async () => {
  const coordinator = makeCoordinator({ retentionMaxRoots: 2 });
  const lease = await coordinator.acquireWriter('project-e', 'writer-e');
  await coordinator.createSyntheticProject({ projectId: 'project-e', title: 'Synthetic', lease });
  await coordinator.mutateSyntheticValue({ projectId: 'project-e', lease, delta: 1 });
