  const before = await coordinator.inspectHistory('project-e');

  await expect(coordinator.mutateSyntheticValue({ projectId: 'project-e', lease, delta: 2 })).rejects.toMatchObject({
    name: 'RetentionRejectedError',
    code: 'PROJECT_HISTORY_RESOURCE_LIMIT',
    rootCount: 3,
    limit: 2
  });
  expect(await coordinator.inspectHistory('project-e')).toEqual(before);

  coordinator.setRetentionMaxRoots(3);
  const published = await coordinator.mutateSyntheticValue({ projectId: 'project-e', lease, delta: 2 });
  const after = await coordinator.inspectHistory('project-e');
  expect(published.revision.document.syntheticValue).toBe(2);
  expect(after.redoRevisionIds).toHaveLength(0);
  expect(after.undoRevisionIds).toHaveLength(1);
});

test('history-only corruption requires an explicit confirm; cancel preserves history and confirm creates no project revision', async () => {
