import { expect, test } from 'vitest';
import { indexedDB as fakeIndexedDB } from 'fake-indexeddb';

import {
  FaultInjectedError,
  RetentionRejectedError,
  WriterFencedError,
  createDurabilityCoordinator
} from '../../src/durability.mjs';

function coordinator(options = {}) {
  return createDurabilityCoordinator({
    indexedDBFactory: fakeIndexedDB,
    databaseName: `s3-mutation-${crypto.randomUUID()}`,
    ...options
  });
}

test('a pre-pointer fault leaves the prior pointer durable while an after-swap fault recovers the replacement', async () => {
  const beforeSwap = coordinator({ faultAt: 'before-pointer-swap' });
  const leaseA = await beforeSwap.acquireWriter('p-a', 'a');
  await beforeSwap.createSyntheticProject({ projectId: 'p-a', lease: leaseA, ignoreFaults: true });
  await expect(beforeSwap.mutateSyntheticValue({ projectId: 'p-a', lease: leaseA, delta: 7 })).rejects.toBeInstanceOf(FaultInjectedError);
  expect((await beforeSwap.recoverProject('p-a', leaseA)).revision.document.syntheticValue).toBe(0);

  const afterSwap = coordinator({ faultAt: 'after-pointer-swap' });
  const leaseB = await afterSwap.acquireWriter('p-b', 'b');
  await afterSwap.createSyntheticProject({ projectId: 'p-b', lease: leaseB, ignoreFaults: true });
  await expect(afterSwap.mutateSyntheticValue({ projectId: 'p-b', lease: leaseB, delta: 7 })).rejects.toBeInstanceOf(FaultInjectedError);
  expect((await afterSwap.recoverProject('p-b', leaseB)).revision.document.syntheticValue).toBe(7);
});

test('takeover fence rejects the stale writer and accepts the new fence', async () => {
  const store = coordinator();
  const stale = await store.acquireWriter('p-c', 'writer-a');
  await store.createSyntheticProject({ projectId: 'p-c', lease: stale });
  const current = await store.acquireWriter('p-c', 'writer-b', { takeover: true });
  await expect(store.mutateSyntheticValue({ projectId: 'p-c', lease: stale, delta: 3 })).rejects.toBeInstanceOf(WriterFencedError);
  expect((await store.mutateSyntheticValue({ projectId: 'p-c', lease: current, delta: 3 })).revision.document.syntheticValue).toBe(3);
});

test('retention rejection preserves a nonempty redo branch, but a permitted durable publish replaces it', async () => {
  const store = coordinator({ retentionMaxRoots: 2 });
  const lease = await store.acquireWriter('p-d', 'writer');
  await store.createSyntheticProject({ projectId: 'p-d', lease });
  await store.mutateSyntheticValue({ projectId: 'p-d', lease, delta: 4 });
  await store.undo({ projectId: 'p-d', lease });
  await expect(store.mutateSyntheticValue({ projectId: 'p-d', lease, delta: 9 })).rejects.toBeInstanceOf(RetentionRejectedError);
  expect((await store.inspectHistory('p-d')).redoRevisionIds).toHaveLength(1);
  store.setRetentionMaxRoots(3);
  await store.mutateSyntheticValue({ projectId: 'p-d', lease, delta: 9 });
  expect((await store.inspectHistory('p-d')).redoRevisionIds).toHaveLength(0);
});

test('history-only corruption changes no pointer on cancel and clears only history after explicit confirm', async () => {
  const store = coordinator();
  const lease = await store.acquireWriter('p-e', 'writer');
  await store.createSyntheticProject({ projectId: 'p-e', lease });
  await store.mutateSyntheticValue({ projectId: 'p-e', lease, delta: 5 });
  await store.undo({ projectId: 'p-e', lease });
  const pointer = await store.readPointer('p-e');
  await store.markHistoryOnlyCorrupt('p-e', lease);
  await expect(store.discardSessionHistory({ projectId: 'p-e', confirmed: false, lease })).resolves.toMatchObject({ status: 'cancelled', createdProjectRevision: false });
  expect((await store.inspectHistory('p-e')).redoRevisionIds).toHaveLength(1);
  await expect(store.discardSessionHistory({ projectId: 'p-e', confirmed: true, lease })).resolves.toMatchObject({ status: 'discarded', createdProjectRevision: false });
  expect(await store.readPointer('p-e')).toEqual(pointer);
  expect((await store.inspectHistory('p-e')).undoRevisionIds).toHaveLength(0);
  expect((await store.inspectHistory('p-e')).redoRevisionIds).toHaveLength(0);
});
